import re
from typing import Any


def prepare_notes(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    required = ("group", "channel", "priority", "text")
    groups: dict[tuple[str, str, str], list[str]] = {}
    for row in rows:
        if not isinstance(row, dict):
            raise TypeError("each row must be a dictionary")
        if any(field not in row for field in required):
            raise ValueError("row is missing a required field")
        if any(not isinstance(row[field], str) for field in required):
            raise TypeError("required fields must be strings")
        key = (row["group"], row["channel"], row["priority"])
        groups.setdefault(key, []).append(row["text"])

    group_codes = {value: index for index, value in enumerate(dict.fromkeys(key[0] for key in groups))}
    channel_codes = {value: index for index, value in enumerate(dict.fromkeys(key[1] for key in groups))}
    priority_codes = {value: index for index, value in enumerate(dict.fromkeys(key[2] for key in groups))}

    result: list[dict[str, Any]] = []
    for key in sorted(groups):
        normalized = re.sub(r"[^a-z0-9]+", " ", " ".join(groups[key]).lower()).strip()
        result.append({
            "group_code": group_codes[key[0]],
            "channel_code": channel_codes[key[1]],
            "priority_code": priority_codes[key[2]],
            "tokens": normalized.split() if normalized else [],
        })
    return result

